// stdlib_rand_kat_xmod — std_rand (L5) PCG32 + xoshiro256** KAT fixture.
//
// Seed 0xDEADBEEF (PCG stream 1): prints 100 pcg32Next outputs as 8-digit
// lowercase hex lines, then 100 xoshiroNext outputs as 16-digit lines, then
// `rand kat ok`. The seeding check initializes two instances with the same
// seed and asserts their first 10 outputs agree.
//
// GREEN (contract): byte-exact stdout `expected.txt` (generated by ref.c) and
// RUNRC=0. A mismatch calls @panic.
const std = @import("std");
const rand = @import("std_rand.zig");

const SEED: u64 = 0xDEADBEEF;

fn hexChar(v: u64) u8 {
    if (v < 10) return @intCast(u8, @intCast(u32, '0') + @intCast(u32, v));
    return @intCast(u8, @intCast(u32, 'a') + @intCast(u32, v - 10));
}

fn writeHexPadded(v: u64, digits: usize) void {
    var buf: [16]u8 = undefined;
    var i: usize = 0;
    while (i < digits) : (i += 1) {
        var sh: u64 = @intCast(u64, (digits - 1 - i) * 4);
        buf[i] = hexChar((v >> sh) & 15);
    }
    std.io.write(buf[0..digits]);
}

fn checkSeeding() void {
    var p1 = rand.pcg32Init(SEED, 1);
    var p2 = rand.pcg32Init(SEED, 1);
    var i: u32 = 0;
    while (i < 10) : (i += 1) {
        if (rand.pcg32Next(&p1) != rand.pcg32Next(&p2)) {
            @panic("pcg32 seeding");
        }
    }
    var x1 = rand.xoshiroInit(SEED);
    var x2 = rand.xoshiroInit(SEED);
    i = 0;
    while (i < 10) : (i += 1) {
        if (rand.xoshiroNext(&x1) != rand.xoshiroNext(&x2)) {
            @panic("xoshiro seeding");
        }
    }
}

pub fn main() void {
    checkSeeding();

    var p = rand.pcg32Init(SEED, 1);
    var i: u32 = 0;
    while (i < 100) : (i += 1) {
        writeHexPadded(@intCast(u64, rand.pcg32Next(&p)), 8);
        std.io.write("\n");
    }

    var x = rand.xoshiroInit(SEED);
    i = 0;
    while (i < 100) : (i += 1) {
        writeHexPadded(rand.xoshiroNext(&x), 16);
        std.io.write("\n");
    }

    std.io.write("rand kat ok\n");
}
